test:
for user in [(5, 15, 'earlier'), (10, 15, 'same start'), (20, 25, 'at end')]:
    actual = mark_interruptions(merge_chunks([(10, 20, 'A')], [user], []))
    agent = next(item for item in actual if item['role'] == 'agent')
    assert agent == {'role': 'agent', 'start': 10, 'end': 20, 'text': 'A', 'interrupted': False}

for user, agent in [((0, 10, 'U'), (10, 20, 'A')), ((0, 15, 'U'), (10, 20, 'A')), ((10, 20, 'U'), (0, 5, 'A'))]:
    marked = mark_interruptions(merge_chunks([agent], [user], []))
    assert insert_gaps(marked) == marked
